mapper.select:
select * from _news 
where news_resion = #{news_resion}
order by news_enddate desc

update _news 
set news_subject=#{news_subject}, news_content=#{news_content}, news_place=#{news_place}, 
news_startdate=#{news_startdate}, news_enddate=#{news_enddate}, news_resion=#{news_resion}, 
news_src=#{news_src}, news_ins=#{news_ins}, news_att=#{news_att} 
where news_id = #{news_id}
